NAV_ICON = ('<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">'
            '<rect x="3" y="3" width="18" height="18" rx="2" /><circle cx="8.5" cy="8.5" r="1.5" />'
            '<polyline points="21 15 16 10 5 21" /></svg>')

def die(msg):
    print("ABORTED, nothing was changed:\n  " + msg); sys.exit(1)

def read(p):
    with open(p, encoding="utf-8") as f: return f.read()

def sub_once(text, old, new, label):
    n = text.count(old)
    if n != 1: die(f"{label}: expected exactly 1 match, found {n}. Anchor:\n  {old!r}")
    return text.replace(old, new)

if not (os.path.isfile("package.json") and os.path.isfile("src/App.tsx") and os.path.isfile("src/pages/SystemPanel.tsx")):
    die("Run this from the AgriPulse client directory (needs package.json, src/App.tsx, src/pages/SystemPanel.tsx).")

pending = {}   # path -> new content

# ---- SystemPanel.tsx ----
sp_path = "src/pages/SystemPanel.tsx"
sp = read(sp_path)
if "image_intelligence" in sp:
    print("SystemPanel.tsx: already patched, skipping")
else:
    sp = sub_once(sp, "import api from '../lib/api';\n",
        "import api from '../lib/api';\nimport { ImageIntelligenceTab } from '../features/image-intelligence';\n", "import")
    sp = sub_once(sp, "'vet_verifications' | 'server';", "'vet_verifications' | 'server' | 'image_intelligence';", "TabId")
    sp = sub_once(sp, "  {\n    section: 'Veterinary',",
        "  {\n    section: 'Intelligence',\n    items: [\n      { id: 'image_intelligence', label: 'Image Intelligence', icon: " + NAV_ICON + " },\n    ],\n  },\n  {\n    section: 'Veterinary',", "NAV")
    sp = sub_once(sp, "  server: { title: 'Server Performance', sub: 'Live system health, resource usage, and process monitoring' },\n",
        "  server: { title: 'Server Performance', sub: 'Live system health, resource usage, and process monitoring' },\n"
        "  image_intelligence: { title: 'Image Intelligence', sub: 'Review image evidence, duplicates, and technical signals' },\n", "TAB_META")
    sp = sub_once(sp, "          {tab === 'vet_verifications' && <VetApprovalsTab />}\n",
        "          {tab === 'vet_verifications' && <VetApprovalsTab />}\n          {tab === 'image_intelligence' && <ImageIntelligenceTab />}\n", "render")
    sp = sub_once(sp, "useState<TabId>('overview');",
        "useState<TabId>(() => (new URLSearchParams(window.location.search).get('tab') === 'image_intelligence' ? 'image_intelligence' : 'overview'));", "initial tab")
    pending[sp_path] = sp

# ---- App.tsx ----
app_path = "src/App.tsx"
app = read(app_path)
if "/system/image-intelligence" in app:
    print("App.tsx: already patched, skipping")
else:
    app = sub_once(app, '      <Route path="/system" element={<SystemRoute />} />\n',
        '      <Route path="/system" element={<SystemRoute />} />\n'
        '      <Route path="/system/image-intelligence" element={<Navigate to="/system?tab=image_intelligence" replace />} />\n', "route")
    pending[app_path] = app

# ---- package.json ----
pkg = json.loads(read("package.json"))
dev = pkg.setdefault("devDependencies", {})
wanted = {"vitest": "^2.1.4", "jsdom": "^25.0.1", "@testing-library/react": "^16.0.1", "@testing-library/dom": "^10.4.0",
          "@testing-library/jest-dom": "^6.6.3", "@testing-library/user-event": "^14.5.2"}
changed = False
for k, v in wanted.items():
    if k not in dev: dev[k] = v; changed = True
scripts = pkg.setdefault("scripts", {})
if "test" not in scripts: scripts["test"] = "vitest run"; changed = True
if changed: pending["package.json"] = json.dumps(pkg, indent=2) + "\n"

# ---- new files ----
for path, content in FILES.items():
    if os.path.exists(path):
        if read(path) == content: continue
        if path in ("vitest.config.ts", "src/test/setup.ts"):
            print(f"{path}: exists and differs, left untouched. Merge manually if tests fail."); continue
    pending[path] = content

# ---- write ----
for path, content in pending.items():
    if os.path.exists(path):
        bak = path + ".bak-image-intel"
        if not os.path.exists(bak): shutil.copy2(path, bak)
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8") as f: f.write(content)
    print("wrote", path)

print("\nDone. Next:\n  npm install\n  npm test\n  npm run build")
